cat > shots.mjs <<'EOF'
import { chromium } from '@playwright/test';
const browser = await chromium.launch();
const pages = ['index','products','pricing','orders','about','contact'];
for (const name of pages) {
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  const fails = [];
  page.on('requestfailed', r => fails.push(r.url()));
  await page.goto(`${process.env.BASE}/${name}.html`);
  await page.waitForTimeout(500);
  await page.screenshot({ path: `${process.env.TMPDIR}/${name}.png`, fullPage: true });
  const overflow = await page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth);
  console.log(name, 'failed:', fails, 'hOverflow:', overflow);
  await page.close();
}
const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
await page.goto(`${process.env.BASE}/index.html`);
await page.screenshot({ path: `${process.env.TMPDIR}/mobile.png`, fullPage: true });
console.log('mobile hOverflow:', await page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth));
await browser.close();
EOF
